package com.dappunq.service;
import com.dappunq.dto.valuation.*; import com.dappunq.model.valuation.*; import com.dappunq.persistence.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service public class StrategyConfigurationService { final JpaUserEntityRepository users; final StrategyConfigRepository configs; final ValuationPersistenceMapper mapper; final HoldingsValuationService holdings; public StrategyConfigurationService(JpaUserEntityRepository u,StrategyConfigRepository c,ValuationPersistenceMapper m,HoldingsValuationService h){users=u;configs=c;mapper=m;holdings=h;} @Transactional public StrategyStateResponse configure(Long id,StrategyRequest r){UserEntity u=users.findById(id).orElseThrow(()->new NoSuchElementException("Usuario inexistente")); StrategyConfig domain=new StrategyConfig(r.estrategia(),r.pesos()); Optional<StrategyConfigEntity> current=configs.findFirstByUserIdAndEstado(id,StrategyStatus.ACTUAL); StrategyStatus st=current.isEmpty()?StrategyStatus.ACTUAL:StrategyStatus.PENDIENTE; if(st==StrategyStatus.PENDIENTE) configs.findFirstByUserIdAndEstado(id,st).ifPresent(configs::delete); StrategyConfigEntity e=configs.save(new StrategyConfigEntity(u,domain.strategy(),mapper.write(domain.weights()),st,Instant.now())); if(st==StrategyStatus.ACTUAL) holdings.revalue(id,e,ExecutionType.MANUAL); return new StrategyStateResponse(e.getEstrategia(),domain.weights(),e.getEstado(),e.getVigenteDesde()); } public StrategyStateResponse get(Long id){StrategyConfigEntity e=configs.findFirstByUserIdAndEstado(id,StrategyStatus.ACTUAL).orElse(null); if(e==null)return new StrategyStateResponse(null,null,StrategyStatus.SIN_ESTRATEGIA,null); return new StrategyStateResponse(e.getEstrategia(),mapper.read(e.getPesos()),e.getEstado(),e.getVigenteDesde());} }
